import type { ServiceAccount } from "@/components/openlmis/service-accounts-page/service-account"

export const MOCK_SERVICE_ACCOUNTS: ServiceAccount[] = [
  {
    token: "6f1c8e2a-41b7-4f3d-9a0e-5c2d7b8e4f19",
    createdDate: "2026-09-28T14:05:00Z",
  },
  {
    token: "b2d94a17-0c6e-4e8b-a3f5-91d7c2e6a0b4",
    createdDate: "2026-07-11T08:42:00Z",
  },
  {
    token: "1e7a3c90-58f2-4b1d-8c64-2a9f0e3d7b51",
    createdDate: "2025-12-02T16:20:00Z",
  },
  {
    token: "9c4f2b68-d3a1-47e0-b5c9-6e8a1f2d3c70",
    createdDate: "2025-03-19T10:11:00Z",
  },
]

// Stand-ins for the keys the server would create, used in turn.
export const MOCK_NEW_TOKENS = [
  "4a8e1d27-6b3f-4c90-8e15-7d2b9f0a6c38",
  "e07b5c19-2d84-4f6a-a1c3-58e9d0b7f264",
  "73d2f0a8-9e41-4b5c-86d7-1f3a2c9e0b85",
]

"use client"

import { AlertCircleIcon, KeyRoundIcon, Trash2Icon } from "lucide-react"
import { type ReactNode, useRef, useState } from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import {
  CopyableValue,
  type CopyState,
} from "@/components/openlmis/copyable-value"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"

import type { ServiceAccount } from "@/components/openlmis/service-accounts-page/service-account"

function DialogError({
  title,
  description,
}: {
  title: string
  description: ReactNode
}) {
  return (
    <Alert variant="destructive">
      <AlertCircleIcon />
      <AlertTitle>{title}</AlertTitle>
      <AlertDescription>{description}</AlertDescription>
    </Alert>
  )
}

type AddServiceAccountDialogProps = CopyState & {
  open: boolean
  /** The account just added; the dialog then shows its key to copy. */
  created?: ServiceAccount | undefined
  /** Called on Add; add the account, then pass it back as `created`. */
  onAdd: () => void
  /** Keeps the dialog open and shows a spinner while the account is added. */
  pending?: boolean
  /** Why adding failed, e.g. "Something went wrong. Check your connection and try again." */
  error?: ReactNode
  /** Called when the dialog closes; clear `created` and `error` here. */
  onClose: () => void
}

/** Asks before adding an account, then shows its new key once to copy. */
export function AddServiceAccountDialog({
  open,
  created,
  onAdd,
  pending = false,
  error,
  onClose,
  ...copy
}: AddServiceAccountDialogProps) {
  const { dialogProps } = useDialogTarget(open || undefined, onClose)
  // Kept until the close animation ends, so the key stays on screen after the caller clears it.
  const [key, setKey] = useState(created)
  if (created && created !== key) setKey(created)
  const props = dialogProps(pending)

  return (
    <AlertDialog
      {...props}
      onOpenChangeComplete={(next) => {
        props.onOpenChangeComplete(next)
        if (!next) setKey(undefined)
      }}
    >
      <AlertDialogContent>
        {key ? (
          <>
            <AlertDialogHeader>
              <AlertDialogMedia>
                <KeyRoundIcon />
              </AlertDialogMedia>
              <AlertDialogTitle>Service Account Added</AlertDialogTitle>
              <AlertDialogDescription>
                Copy the key into the system that will use it. It stays listed
                here until you delete it.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <CopyableValue
              copiedLabel="Key Copied"
              copyLabel="Copy Key"
              focusOnMount
              value={key.token}
              {...copy}
            />
            <AlertDialogFooter>
              <Button onClick={onClose}>Done</Button>
            </AlertDialogFooter>
          </>
        ) : (
          <>
            <AlertDialogHeader>
              <AlertDialogMedia>
                <KeyRoundIcon />
              </AlertDialogMedia>
              <AlertDialogTitle>Add A Service Account?</AlertDialogTitle>
              <AlertDialogDescription>
                OpenLMIS creates a new key. Any system that sends it can use the
                API until the key is deleted.
              </AlertDialogDescription>
            </AlertDialogHeader>
            {error && (
              <DialogError
                description={error}
                title="Could Not Add Service Account"
              />
            )}
            <AlertDialogFooter>
              <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
              <Button disabled={pending} focusableWhenDisabled onClick={onAdd}>
                {pending && <Spinner data-icon="inline-start" />}
                Add Service Account
              </Button>
            </AlertDialogFooter>
          </>
        )}
      </AlertDialogContent>
    </AlertDialog>
  )
}

type DeleteServiceAccountDialogProps = CopyState & {
  /** The key to delete; opens the dialog while set. */
  token: string | undefined
  /** Called on Delete; delete it, then clear `token` to close. */
  onDelete: (token: string) => void
  pending?: boolean
  /** Why deleting failed. */
  error?: ReactNode
  onClose: () => void
}

/** Confirms deleting a key, which stops every system that uses it. */
export function DeleteServiceAccountDialog({
  token,
  onDelete,
  pending = false,
  error,
  onClose,
  ...copy
}: DeleteServiceAccountDialogProps) {
  const { shown, dialogProps } = useDialogTarget(token, onClose)
  const cancelRef = useRef<HTMLButtonElement>(null)

  return (
    <AlertDialog {...dialogProps(pending)}>
      {/* Cancel first, not the key's Copy button: deleting cannot be undone. */}
      <AlertDialogContent initialFocus={cancelRef}>
        <AlertDialogHeader>
          <AlertDialogMedia>
            <Trash2Icon />
          </AlertDialogMedia>
          <AlertDialogTitle>Delete This Service Account?</AlertDialogTitle>
          <AlertDialogDescription>
            Any system that uses this key stops working at once. This cannot be
            undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        {shown && (
          <CopyableValue
            copiedLabel="Key Copied"
            copyLabel="Copy Key"
            value={shown}
            {...copy}
          />
        )}
        {error && (
          <DialogError
            description={error}
            title="Could Not Delete Service Account"
          />
        )}
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending} ref={cancelRef}>
            Cancel
          </AlertDialogCancel>
          <Button
            disabled={pending}
            focusableWhenDisabled
            onClick={() => shown && onDelete(shown)}
            variant="destructive"
          >
            {pending && <Spinner data-icon="inline-start" />}
            Delete
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** An API key; `token` is the key an integration sends, and it never expires. */
export type ServiceAccount = {
  token: string
  /** When it was added, as an ISO date and time. */
  createdDate: string
}

"use client"

import type { PaginationState } from "@tanstack/react-table"
import { KeyRoundIcon } from "lucide-react"
import { useCallback, useMemo, useRef, useState } from "react"

import type { ServiceAccount } from "@/components/openlmis/service-accounts-page/service-account"
import {
  AddServiceAccountDialog,
  DeleteServiceAccountDialog,
} from "@/components/openlmis/service-accounts-page/service-account-form-dialog"
import {
  ServiceAccountsTable,
  ServiceAccountsToolbar,
} from "@/components/openlmis/service-accounts-page/service-accounts-table"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"

import { MOCK_NEW_TOKENS, MOCK_SERVICE_ACCOUNTS } from "@/components/openlmis/service-accounts-page/mock-service-accounts"

type Notice = {
  tone: "success" | "warning"
  title: string
  description: string
}

/** The service accounts screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function ServiceAccountsPage() {
  const [accounts, setAccounts] = useState(MOCK_SERVICE_ACCOUNTS)
  const [newestFirst, setNewestFirst] = useState(true)
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })
  const [adding, setAdding] = useState(false)
  const [created, setCreated] = useState<ServiceAccount>()
  const [deleting, setDeleting] = useState<string>()
  const [notice, setNotice] = useState<Notice>()
  // Mocked copy: a real app writes to the clipboard in onCopy, then sets this.
  const [copiedToken, setCopiedToken] = useState<string>()
  // Counts every add, so a new key never repeats one already listed or deleted.
  const added = useRef(0)

  // Every account is in memory, so sorting and paging happen here.
  const sorted = useMemo(
    () =>
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
      [...accounts].sort((a, b) =>
        newestFirst
          ? b.createdDate.localeCompare(a.createdDate)
          : a.createdDate.localeCompare(b.createdDate)
      ),
    [accounts, newestFirst]
  )
  const lastPage = Math.max(
    0,
    Math.ceil(sorted.length / pagination.pageSize) - 1
  )
  // Deleting the last key on a page holds the table to the last page that exists.
  const page = useMemo(
    () => ({
      ...pagination,
      pageIndex: Math.min(pagination.pageIndex, lastPage),
    }),
    [pagination, lastPage]
  )
  const rows = useMemo(
    () =>
      sorted.slice(
        page.pageIndex * page.pageSize,
        (page.pageIndex + 1) * page.pageSize
      ),
    [sorted, page]
  )

  const openAdd = useCallback(() => {
    setNotice(undefined)
    setAdding(true)
  }, [])
  const openDelete = useCallback((token: string) => {
    setNotice(undefined)
    setDeleting(token)
  }, [])
  const onCopiedChange = useCallback((copied: boolean) => {
    if (!copied) setCopiedToken(undefined)
  }, [])
  const changeSort = useCallback((next: boolean) => {
    setNewestFirst(next)
    setPagination((current) => ({ ...current, pageIndex: 0 }))
  }, [])

  const add = () => {
    const count = added.current++
    const base = MOCK_NEW_TOKENS[count % MOCK_NEW_TOKENS.length]
    const round = Math.floor(count / MOCK_NEW_TOKENS.length)
    const account = {
      // Past the fixtures, the round number replaces the key's tail so it stays unique.
      token:
        round === 0 || !base
          ? (base ?? `key-${count + 1}`)
          : `${base.slice(0, -4)}${round.toString(16).padStart(4, "0")}`,
      createdDate: new Date().toISOString(),
    }
    setAccounts((current) => [...current, account])
    setCreated(account)
  }
  const remove = (token: string) => {
    setAccounts((current) =>
      current.filter((account) => account.token !== token)
    )
    setNotice({
      tone: "success",
      title: "Service Account Deleted",
      description: `The key ${token} no longer works.`,
    })
    setDeleting(undefined)
  }

  return (
    <Workspace>
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <KeyRoundIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Service Accounts</WorkspaceTitle>
          <WorkspaceDescription>
            API keys that let other systems use the OpenLMIS API.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        <div className="flex flex-col gap-4 @4xl/main:gap-6">
          {notice && (
            <Callout title={notice.title} tone={notice.tone}>
              {notice.description}
            </Callout>
          )}
          <ServiceAccountsToolbar onAdd={openAdd} />
          <ServiceAccountsTable
            accounts={rows}
            newestFirst={newestFirst}
            onAdd={openAdd}
            copiedToken={copiedToken}
            onCopy={setCopiedToken}
            onCopiedChange={onCopiedChange}
            onDelete={openDelete}
            onNewestFirstChange={changeSort}
            onPaginationChange={setPagination}
            pagination={page}
            rowCount={sorted.length}
          />
        </div>
      </WorkspaceContent>
      <AddServiceAccountDialog
        created={created}
        onAdd={add}
        onClose={() => {
          setAdding(false)
          setCreated(undefined)
        }}
        copied={created !== undefined && copiedToken === created.token}
        onCopy={setCopiedToken}
        onCopiedChange={onCopiedChange}
        open={adding}
      />
      <DeleteServiceAccountDialog
        onClose={() => setDeleting(undefined)}
        copied={deleting !== undefined && copiedToken === deleting}
        onCopy={setCopiedToken}
        onCopiedChange={onCopiedChange}
        onDelete={remove}
        token={deleting}
      />
    </Workspace>
  )
}

"use client"

import {
  createColumnHelper,
  functionalUpdate,
  type PaginationState,
  useTable,
} from "@tanstack/react-table"
import { EllipsisIcon, KeyRoundIcon, PlusIcon, Trash2Icon } from "lucide-react"
import { useMemo } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTable,
  DataTableColumnHeader,
  DataTableEmpty,
  DataTableError,
  type DataTableFeatures,
  DataTablePagination,
  DataTableSkeleton,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import { useMenuOpensDialog } from "@/components/blocks/openlmis/data-table/row-actions"
import { ListToolbar } from "@/components/blocks/openlmis/list-toolbar"
import { CopyButton } from "@/components/openlmis/copyable-value"

import type { ServiceAccount } from "@/components/openlmis/service-accounts-page/service-account"

const columnHelper = createColumnHelper<DataTableFeatures, ServiceAccount>()

type RowActions = {
  onDelete: ((token: string) => void) | undefined
  copiedToken: string | undefined
  onCopy: ((token: string) => void) | undefined
  onCopiedChange: ((copied: boolean) => void) | undefined
}

function createColumns(
  formatDate: (date: Date) => string,
  { onDelete, copiedToken, onCopy, onCopiedChange }: RowActions
) {
  return columnHelper.columns([
    columnHelper.accessor("createdDate", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Created" />
      ),
      cell: ({ getValue }) => (
        <span className="whitespace-normal">
          {formatDate(new Date(getValue()))}
        </span>
      ),
      meta: { className: "@xl/table:w-56" },
    }),
    columnHelper.accessor("token", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Key" />
      ),
      enableSorting: false,
      cell: ({ getValue }) => (
        <div className="flex items-center gap-1 whitespace-normal">
          <span className="font-mono text-sm break-all" dir="ltr">
            {getValue()}
          </span>
          <CopyButton
            copied={getValue() === copiedToken}
            copiedLabel="Key Copied"
            copyLabel="Copy Key"
            onCopiedChange={onCopiedChange}
            onCopy={onCopy}
            value={getValue()}
          />
        </div>
      ),
    }),
    ...(onDelete
      ? [
          columnHelper.display({
            id: "actions",
            header: () => <span className="sr-only">Actions</span>,
            cell: ({ row }) => (
              <KeyActions onDelete={onDelete} token={row.original.token} />
            ),
            meta: { className: "w-16" },
          }),
        ]
      : []),
  ])
}

function KeyActions({
  token,
  onDelete,
}: {
  token: string
  onDelete: (token: string) => void
}) {
  const menu = useMenuOpensDialog()

  return (
    <div className="flex justify-end">
      <DropdownMenu onOpenChange={menu.onOpenChange}>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions For Key ${token}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          className="w-auto"
          finalFocus={menu.finalFocus}
        >
          <DropdownMenuItem
            onClick={menu.opensDialog(() => onDelete(token))}
            variant="destructive"
          >
            <Trash2Icon />
            Delete
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

const NO_KEYS: ServiceAccount[] = []

const getRowId = (account: ServiceAccount) => account.token

type ServiceAccountsTableProps = {
  /** One page of accounts; a skeleton shows until it is set. */
  accounts: readonly ServiceAccount[] | undefined
  /** Every account, across all pages. */
  rowCount: number
  pagination: PaginationState
  onPaginationChange: (pagination: PaginationState) => void
  /** Newest first by default; sorting is left to the caller. */
  newestFirst?: boolean
  onNewestFirstChange?: (newestFirst: boolean) => void
  /** Offered when there are no accounts. */
  onAdd?: (() => void) | undefined
  /** Without it, the row menu is left out. */
  onDelete?: ((token: string) => void) | undefined
  /** The key whose Copy button shows a tick. */
  copiedToken?: string | undefined
  /** Called on a key's Copy button; copy it, then pass it as `copiedToken`. */
  onCopy?: ((token: string) => void) | undefined
  /** Called with `false` when the copied key's button loses focus or the pointer. */
  onCopiedChange?: ((copied: boolean) => void) | undefined
  /** Dims the rows while the next page loads. */
  isStale?: boolean
  /** Loading failed; shows the error with Try Again. */
  onRetry?: (() => void) | undefined
  /** The language dates and times are shown in. */
  dateLanguage?: string
}

/** API keys with when each was added, a page at a time; the caller must clamp `pageIndex` to the last page when rows shrink. */
export function ServiceAccountsTable({
  accounts,
  rowCount,
  pagination,
  onPaginationChange,
  newestFirst = true,
  onNewestFirstChange,
  onAdd,
  onDelete,
  copiedToken,
  onCopy,
  onCopiedChange,
  isStale = false,
  onRetry,
  dateLanguage = "en-US",
}: ServiceAccountsTableProps) {
  const formatDate = useMemo(
    () =>
      // UTC, named, so a server render and the browser print the same time.
      new Intl.DateTimeFormat(dateLanguage, {
        year: "numeric",
        month: "short",
        day: "numeric",
        hour: "numeric",
        minute: "2-digit",
        timeZone: "UTC",
        timeZoneName: "short",
      }).format,
    [dateLanguage]
  )
  const columns = useMemo(
    () =>
      createColumns(formatDate, {
        onDelete,
        copiedToken,
        onCopy,
        onCopiedChange,
      }),
    [formatDate, onDelete, copiedToken, onCopy, onCopiedChange]
  )
  // Memoized: the table compares controlled state by reference and would reset it every render.
  const sorting = useMemo(
    () => [{ id: "createdDate", desc: newestFirst }],
    [newestFirst]
  )
  const table = useTable({
    features: dataTableFeatures,
    columns,
    data: (accounts ?? NO_KEYS) as ServiceAccount[],
    getRowId,
    rowCount,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    enableSorting: Boolean(onNewestFirstChange),
    state: { pagination, sorting },
    onPaginationChange: (updater) =>
      onPaginationChange(functionalUpdate(updater, pagination)),
    onSortingChange: (updater) => {
      const [next] = functionalUpdate(updater, sorting)
      if (next) onNewestFirstChange?.(next.desc)
    },
  })

  if (onRetry)
    return (
      <DataTableError
        description="Something went wrong while loading the service accounts. Try again."
        onRetry={onRetry}
        title="Service Accounts Could Not Load"
      />
    )
  if (accounts === undefined)
    return <DataTableSkeleton rowCount={pagination.pageSize} table={table} />

  return (
    <DataTable
      empty={
        <DataTableEmpty
          action={
            onAdd && (
              <Button onClick={onAdd}>
                <PlusIcon data-icon="inline-start" />
                Add Service Account
              </Button>
            )
          }
          description="Add one to give another system access to the API."
          icon={<KeyRoundIcon />}
          title="No Service Accounts"
        />
      }
      footer={rowCount > 0 && <DataTablePagination table={table} />}
      isStale={isStale}
      table={table}
    />
  )
}

/** The Add button above the table, at the end with room and full width without. */
export function ServiceAccountsToolbar({ onAdd }: { onAdd: () => void }) {
  return (
    <ListToolbar>
      <div className="w-full @2xl/toolbar:ms-auto @2xl/toolbar:w-auto">
        <Button className="w-full" onClick={onAdd}>
          <PlusIcon data-icon="inline-start" />
          Add Service Account
        </Button>
      </div>
    </ListToolbar>
  )
}

import { ServiceAccountsPage } from "@/components/openlmis/service-accounts-page/service-accounts-page"

// A Next.js App Router route; in any other React app, render ServiceAccountsPage from your own route.
export default function Page() {
  return <ServiceAccountsPage />
}
